#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a;
    long long length;
    long long m;
    cin >> a >> length >> m;
    vector<string> words(m);
    for (int i = 0; i < m; i++) {
        cin >> words[i];
    }

    const long long MOD = 1000000007;
    int alpha = (int)a;
    vector<vector<int>> nxt(1, vector<int>(alpha, -1));
    vector<int> fail(1, 0);
    vector<char> bad(1, 0);
    for (long long wi = 0; wi < m; wi++) {
        int node = 0;
        for (char ch : words[wi]) {
            int c = ch - 'a';
            if (nxt[node][c] == -1) {
                nxt[node][c] = (int)nxt.size();
                nxt.push_back(vector<int>(alpha, -1));
                fail.push_back(0);
                bad.push_back(0);
            }
            node = nxt[node][c];
        }
        bad[node] = 1;
    }
    vector<int> queue;
    for (int c = 0; c < alpha; c++) {
        int v = nxt[0][c];
        if (v == -1) nxt[0][c] = 0;
        else queue.push_back(v);
    }
    for (size_t head = 0; head < queue.size(); head++) {
        int u = queue[head];
        if (bad[fail[u]]) bad[u] = 1;
        for (int c = 0; c < alpha; c++) {
            int v = nxt[u][c];
            if (v == -1) {
                nxt[u][c] = nxt[fail[u]][c];
            } else {
                fail[v] = nxt[fail[u]][c];
                queue.push_back(v);
            }
        }
    }
    int states = (int)nxt.size();
    vector<long long> dp(states, 0), cur(states, 0);
    dp[0] = 1;
    for (long long step = 0; step < length; step++) {
        fill(cur.begin(), cur.end(), 0);
        for (int u = 0; u < states; u++) {
            if (dp[u] == 0) continue;
            for (int c = 0; c < alpha; c++) {
                int v = nxt[u][c];
                if (!bad[v]) cur[v] = (cur[v] + dp[u]) % MOD;
            }
        }
        dp = cur;
    }
    long long total = 0;
    for (int u = 0; u < states; u++) total = (total + dp[u]) % MOD;
    cout << total << "\n";

    return 0;
}

