import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long a = Long.parseLong(next());
        long length = Long.parseLong(next());
        long m = Long.parseLong(next());
        String[] words = new String[(int) m];
        for (int i = 0; i < words.length; i++) {
            words[i] = next();
        }

        long MOD = 1000000007L;
        int alpha = (int) a;
        int cap = 1;
        for (int wi = 0; wi < m; wi++) cap += words[wi].length();
        int[][] nxt = new int[cap][alpha];
        for (int[] row : nxt) Arrays.fill(row, -1);
        int[] fail = new int[cap];
        boolean[] bad = new boolean[cap];
        int size = 1;
        for (int wi = 0; wi < m; wi++) {
            int node = 0;
            for (int p = 0; p < words[wi].length(); p++) {
                int c = words[wi].charAt(p) - 'a';
                if (nxt[node][c] == -1) nxt[node][c] = size++;
                node = nxt[node][c];
            }
            bad[node] = true;
        }
        int[] queue = new int[size];
        int tail = 0;
        for (int c = 0; c < alpha; c++) {
            int v = nxt[0][c];
            if (v == -1) nxt[0][c] = 0;
            else queue[tail++] = v;
        }
        for (int head = 0; head < tail; head++) {
            int u = queue[head];
            if (bad[fail[u]]) bad[u] = true;
            for (int c = 0; c < alpha; c++) {
                int v = nxt[u][c];
                if (v == -1) {
                    nxt[u][c] = nxt[fail[u]][c];
                } else {
                    fail[v] = nxt[fail[u]][c];
                    queue[tail++] = v;
                }
            }
        }
        long[] dp = new long[size];
        long[] cur = new long[size];
        dp[0] = 1;
        for (int step = 0; step < length; step++) {
            Arrays.fill(cur, 0);
            for (int u = 0; u < size; u++) {
                if (dp[u] == 0) continue;
                for (int c = 0; c < alpha; c++) {
                    int v = nxt[u][c];
                    if (!bad[v]) cur[v] = (cur[v] + dp[u]) % MOD;
                }
            }
            long[] swap = dp;
            dp = cur;
            cur = swap;
        }
        long total = 0;
        for (int u = 0; u < size; u++) total = (total + dp[u]) % MOD;
        System.out.println(total);
    }
}
